// request holds, so the sweep cannot deadlock with the request locks above.
func (q *Queries) SweepExpireOutcomeDiscards(ctx context.Context, arg SweepExpireOutcomeDiscardsParams) (int64, error) {
	result, err := q.db.Exec(ctx, sweepExpireOutcomeDiscards, arg.Now, arg.GraceSeconds)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
